39	// Parse <a href="https://matrix.to/#/@user:server">@DisplayName</a> tags from
40	// formatted_body HTML into a lowercase-displayName → userId map.
41	// This is the sync fast path — no profile loading needed.
42	const parseMentionMapFromHtml = (html: string): Map<string, string> => {
43	  const regex =
44	    /<a[^>]+href="https:\/\/matrix\.to\/#\/(@[^"]+)"[^>]*>@?([^<]+)<\/a>/gi;
45	  const matches = Array.from(html.matchAll(regex));
46	  return new Map(matches.map((m) => [m[2].toLowerCase(), m[1]]));
47	};
