49	export const TextMessage: FC<Props> = ({
50	  roomId,
51	  event,
52	  isPreviousSameSender,
53	  onMemberPress,
54	}) => {
55	  const [messageWidth, setMessageWidth] = useState(116);
56	  const isUser = event.isOwn;
57	  const sender = event.senderProfile;
58	  const senderId = event.sender;
59	  const seenByUsers = TimelineService.getReadReceiptUsers(event);
60	  const [mentionMap, setMentionMap] = useState<Map<string, string>>(new Map());
61	  // Some clients (Element X) put raw markdown links in the body:
62	  // [@Name](matrix.to/#/@user:server)  — link text has @
63	  // [Name](matrix.to/#/@user:server)   — link text without @
64	  // Detect by the /#/@ pattern in the URL (user permalink) and normalize to @Name.
65	  const content = cleanMentions(getEventTextContent(event));
66	  const maxWidth = width - 60;
67	  const setScrollToEventId = useSetAtom(TimelineAtoms.scrollToEventId);
68	
69	  const { formattedBody, mentionUserIds, isEdited } = useMemo(() => {
70	    if (event.content.tag !== TimelineItemContent_Tags.MsgLike)
71	      return { formattedBody: undefined, mentionUserIds: [], isEdited: false };
72	    const kind = event.content.inner.content.kind;
73	    if (kind?.tag !== MsgLikeKind_Tags.Message) {
74	      return { formattedBody: undefined, mentionUserIds: [], isEdited: false };
75	    }
76	    const msgType = kind.inner.content.msgType;
77	    const html =
78	      msgType?.tag === MessageType_Tags.Text
79	        ? msgType.inner.content.formatted?.body
80	        : undefined;
81	    return {
82	      formattedBody: html,
83	      mentionUserIds: kind.inner.content.mentions?.userIds ?? [],
84	      isEdited: kind.inner.content.isEdited,
85	    };
86	  }, [event]);
87	
88	  useEffect(() => {
89	    // Fast path: extract mention map directly from formatted_body HTML
90	    if (formattedBody) {
91	      const map = parseMentionMapFromHtml(formattedBody);
92	      if (map.size > 0) {
93	        setMentionMap(map);
94	        return;
95	      }
96	    }
97	
98	    // Fallback: load profiles for mentioned user IDs (messages without formatted_body)
99	    if (!mentionUserIds.length) return;
100	    const client = MatrixCore.getClient();
101	    Promise.allSettled(mentionUserIds.map((id) => client.getProfile(id))).then(
102	      (results) => {
103	        const map = new Map<string, string>();
104	        results.forEach((result, i) => {
105	          const userId = mentionUserIds[i];
106	          const displayName =
107	            result.status === "fulfilled"
108	              ? (result.value.displayName ?? userId)
109	              : userId;
110	          map.set(displayName.toLowerCase(), userId);
111	        });
112	        setMentionMap(map);
113	      },
114	    );
115	  }, [formattedBody, mentionUserIds]);
116	
117	  const replyPayload = useMemo(() => {
118	    if (event.content.tag !== TimelineItemContent_Tags.MsgLike) return null;
119	
120	    const inReplyTo = event.content.inner.content.inReplyTo;
121	
122	    if (!inReplyTo) return null;
123	
124	    const eventDetails = inReplyTo.event();
125	    if (eventDetails.tag !== EmbeddedEventDetails_Tags.Ready) return null;
126	
127	    const senderName =
128	      eventDetails.inner.senderProfile.tag === ProfileDetails_Tags.Ready
129	        ? (eventDetails.inner.senderProfile.inner.displayName ??
130	          eventDetails.inner.sender)
131	        : eventDetails.inner.sender;
132	
133	    let mediaSource: { source: MediaSourceInterface; mimetype: string } | null =
134	      null;
135	    const replyContent = eventDetails.inner.content;
136	
137	    if (replyContent.tag === TimelineItemContent_Tags.MsgLike) {
138	      const kind = replyContent.inner.content.kind;
139	      if (kind?.tag === MsgLikeKind_Tags.Message) {
140	        const msgType = kind.inner.content.msgType;
141	        if (msgType?.tag === MessageType_Tags.Image) {
142	          mediaSource = {
143	            source: msgType.inner.content.source,
144	            mimetype: msgType.inner.content.info?.mimetype || "image/jpeg",
145	          };
146	        }
147	        if (msgType?.tag === MessageType_Tags.Video) {
148	          mediaSource = {
149	            source: msgType.inner.content.source,
150	            mimetype: msgType.inner.content.info?.mimetype || "video/mp4",
151	          };
152	        }
153	      }
154	    }
155	
156	    return {
157	      eventId: inReplyTo.eventId(),
158	      senderName,
159	      content: getMessageTextContent(eventDetails.inner.content),
160	      mediaSource,
161	    };
162	  }, [event]);
163	
164	  const handleReplyPress = useCallback(() => {
165	    if (replyPayload) setScrollToEventId(replyPayload.eventId);
166	  }, [replyPayload, setScrollToEventId]);
167	
168	  return (
169	    <Block
170	      align={isUser ? "flex-end" : "flex-start"}
