181	        <Block flexDirection={isUser ? "row-reverse" : "row"}>
182	          <Block
183	            paddings={12}
184	            background={isUser ? Colors.primary : Colors.message}
185	            border={{ borderRadius: 24 }}
186	            align="stretch"
187	            gap={12}
188	            onLayout={(e) => setMessageWidth(e.nativeEvent.layout.width)}
189	            maxWidth={maxWidth}
190	          >
191	            <ReplyPayload
192	              replyPayload={replyPayload}
193	              onPress={handleReplyPress}
194	            />
195	            <Block
196	              flexDirection={isUser ? "row-reverse" : "row"}
